import * as THREE from 'three';

/* Trạng thái camera dùng chung giữa camera.ts, tour.ts và UI */
export type CameraMode = 'orbit' | 'fly' | 'drive' | 'tpDrive' | 'hrDrive' | 'walk' | 'tour' | 'storm' | 'swRide';   // storm: camera theo hành trình kịch bản bão; swRide: ngồi cabin Vòng quay Mặt Trời (camera do SunWheel.update đặt)
