/* ============================ Tự khám phá: mô hình bay dù lượn ============================
   Thuần toán học, không đụng cảnh. Hướng bay (cos yaw, 0, −sin yaw), cùng quy ước với `walk` trong views/camera.ts:
   yaw tăng là rẽ trái, bank > 0 là nghiêng trái. Mọi thông số ở CONFIG.explore. */
import * as THREE from 'three';
import { CONFIG } from '../config';

const C = CONFIG.explore;

export interface GliderState { pos: THREE.Vector3; yaw: number; bank: number }
export interface GliderInput { turn: -1 | 0 | 1; climb: -1 | 0 | 1 }

/* Trạng thái ban đầu tại điểm cất cánh */
export function exCreate(): GliderState {
  return { pos: new THREE.Vector3(C.takeoff[0], C.takeoff[1], C.takeoff[2]), yaw: C.takeoffYaw, bank: 0 };
}

const wrapPi = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

/* Lái về tâm khung khi sát mép: trả hướng rẽ hiệu lực (−1..1) thay cho phím người chơi */
function exTurnEff(s: GliderState, turn: number): number {
  const b = C.bounds, m = C.returnMargin;
  const d = Math.min(s.pos.x - b.x0, b.x1 - s.pos.x, s.pos.z - b.z0, b.z1 - s.pos.z);   // khoảng cách ngắn nhất tới mép khung
  if (d >= m) return turn;
  const tx = (b.x0 + b.x1) / 2 - s.pos.x, tz = (b.z0 + b.z1) / 2 - s.pos.z, tl = Math.hypot(tx, tz) || 1;
  const dot = (Math.cos(s.yaw) * tx - Math.sin(s.yaw) * tz) / tl;   // hướng bay · hướng tới tâm
  if (dot >= 0.3) return turn;   // đang bay vào trong: giữ phím người chơi
  const delta = wrapPi(Math.atan2(-tz, tx) - s.yaw);   // yaw hướng tâm − yaw hiện tại
  const sg = delta >= 0 ? 1 : -1;
  if (d <= 0.25 * m) return sg;
  const w = 1 - d / m;
  return turn + (sg - turn) * w;
}

/* Một bước mô phỏng: không cấp phát */
export function exStep(s: GliderState, inp: GliderInput, dt: number): void {
  const turn = exTurnEff(s, inp.turn);
  s.bank += (turn * C.bankMax - s.bank) * Math.min(1, C.bankRate * dt);
  s.yaw += C.turnRate * (s.bank / C.bankMax) * dt;
  s.pos.x += Math.cos(s.yaw) * C.speed * dt;
  s.pos.z -= Math.sin(s.yaw) * C.speed * dt;
  s.pos.y = Math.min(C.ceiling, Math.max(C.floor, s.pos.y + inp.climb * C.climbRate * dt));
  const b = C.bounds;   // kẹp cứng: không bao giờ vượt khung
  s.pos.x = Math.min(b.x1, Math.max(b.x0, s.pos.x));
  s.pos.z = Math.min(b.z1, Math.max(b.z0, s.pos.z));
}

/* Phím giữ → đầu vào lái: A/← trái, D/→ phải, W/↑ lên, S/↓ xuống; hai phím ngược nhau triệt tiêu */
export function exInputFromKeys(keys: Set<string>): GliderInput {
  const turn = (keys.has('a') || keys.has('arrowleft') ? 1 : 0) - (keys.has('d') || keys.has('arrowright') ? 1 : 0);
  const climb = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
  return { turn: turn as -1 | 0 | 1, climb: climb as -1 | 0 | 1 };
}
/* ============================ Tự khám phá: camera bám đuôi ============================
   Camera đích = pos − forward·back + up·up; trễ mũ theo CONFIG.explore.chase.lag; nhìn vào pos + forward·30. */
import * as THREE from 'three';
import { CONFIG } from '../config';
import type { GliderState } from './flight';

const K = CONFIG.explore.chase;
const _want = new THREE.Vector3();

export function exChase(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: GliderState, dt: number, snap = false): void {
  const fx = Math.cos(s.yaw), fz = -Math.sin(s.yaw);
  _want.set(s.pos.x - fx * K.back, s.pos.y + K.up, s.pos.z - fz * K.back);
  if (snap) camera.position.copy(_want);
  else camera.position.lerp(_want, 1 - Math.exp(-dt / K.lag));
  target.set(s.pos.x + fx * 30, s.pos.y, s.pos.z + fz * 30);
  camera.lookAt(target);
}
/* ============================ Tự khám phá: mô hình dù lượn ============================
   Một Mesh duy nhất (cánh vòm + dây + người treo + dải đèn mép cánh), gộp bằng mergeGeometries, vertex color.
   Hệ cục bộ: +X là hướng bay, +Y lên, +Z bên phải. Dải đèn đêm là emissiveMap (canvas 2×1 điểm ảnh), cường độ đọc shared.uNight.
   Mọi thông số nằm ở CONFIG.explore.glider (span, lines = khoảng treo, lineCount, chord, arch, segs). */
import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { CONFIG } from '../config';
import { shared } from '../core/shared';
import type { GliderState } from './flight';

const G = CONFIG.explore.glider;
const UV_DARK = 0.25, UV_LIT = 0.75;         // u trên emissiveMap: nửa tối / nửa sáng

/* Gán uv và màu đỉnh cho hình học không chỉ số */
function exPaint(g: THREE.BufferGeometry, rgb: number[], u: number): THREE.BufferGeometry {
  const n = g.attributes.position.count, col = new Float32Array(n * 3), uv = new Float32Array(n * 2);
  for (let i = 0; i < n; i++) { col.set(rgb, i * 3); uv[i * 2] = u; uv[i * 2 + 1] = 0.5; }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  return g;
}

/* Dải cánh vòm giữa hai mặt cắt: lệch x0..x1 theo hướng bay, cong xuống ở hai đầu */
function exWingStrip(chord0: number, chord1: number, rgb: number[], u: number, lift: number): THREE.BufferGeometry {
  const pos: number[] = [];
  const half = G.span / 2;
  for (let i = 0; i < G.segs; i++) {
    const ta = -1 + 2 * i / G.segs, tb = -1 + 2 * (i + 1) / G.segs;
    const pa = (t: number, x: number) => [x, -G.arch * half * t * t + lift, t * half];
    const a0 = pa(ta, chord0), a1 = pa(ta, chord1), b0 = pa(tb, chord0), b1 = pa(tb, chord1);
    pos.push(...a0, ...b0, ...a1, ...a1, ...b0, ...b1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.computeVertexNormals();
  return exPaint(g, rgb, u);
}

/* Hộp mảnh nối hai điểm (dây treo) */
function exLine(a: THREE.Vector3, b: THREE.Vector3): THREE.BufferGeometry {
  const d = b.clone().sub(a), len = d.length();
  const g = new THREE.BoxGeometry(0.03, len, 0.03).toNonIndexed();
  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize()));
  g.translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
  g.deleteAttribute('uv');
  return exPaint(g, [0.15, 0.15, 0.15], UV_DARK);
}

/* Texture phát sáng: nửa trái đen, nửa phải trắng */
function exGlowMap(): THREE.CanvasTexture {
  const c = document.createElement('canvas'); c.width = 2; c.height = 1;
  const x = c.getContext('2d')!;
  x.fillStyle = '#000'; x.fillRect(0, 0, 1, 1);
  x.fillStyle = '#fff'; x.fillRect(1, 0, 1, 1);
  const t = new THREE.CanvasTexture(c);
  t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
